<?php
final class GeminiService {
    private PDO $pdo;
    public function __construct(PDO $pdo){$this->pdo=$pdo;}
    private function setting(string $k):string{$st=$this->pdo->prepare('SELECT setting_value FROM system_settings WHERE setting_key=?');$st->execute([$k]);return (string)($st->fetchColumn()?:'');}
    public function status():array{$v=$this->setting('GEMINI_API_KEY');return ['status'=>'success','hasKey'=>$v!=='','configured'=>$v!=='','maskedKey'=>$v!==''?substr($v,0,4).'••••'.substr($v,-4):'','masked'=>$v!==''?substr($v,0,4).'••••'.substr($v,-4):''];}
    public function saveKey(string $key):array{$key=trim($key);if($key==='')throw new RuntimeException('API key kosong.');$st=$this->pdo->prepare('INSERT INTO system_settings(setting_key,setting_value,updated_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()');$st->execute(['GEMINI_API_KEY',$key]);return ['status'=>'success','message'=>'Gemini API key tersimpan di server lokal.'];}
    public function extractInvoice(array $p):array{
        $key=$this->setting('GEMINI_API_KEY');if($key==='')return ['status'=>'error','code'=>'GEMINI_KEY_MISSING','message'=>'Gemini API key belum disimpan. Gunakan Input Manual atau isi API key pada Pengaturan.'];if(!function_exists('curl_init'))throw new RuntimeException('PHP cURL belum aktif pada XAMPP.');$file=(array)($p['file_invoice']??$p['file']??[]);$base64=(string)($file['base64']??$p['base64']??'');$mime=(string)($file['mimeType']??$p['mimeType']??'image/jpeg');if($base64==='')throw new RuntimeException('File faktur belum tersedia.');$base64=preg_replace('#^data:[^;]+;base64,#','',$base64);$prompt='Baca faktur pembelian supplier Indonesia ini. Kembalikan JSON valid saja dengan struktur: {supplier:{nama,alamat,no_telepon},invoice:{no_faktur,tanggal,waktu,status_pembayaran,metode_pembayaran},items:[{raw_name,kode_item_supplier,qty,satuan,harga_satuan,diskon_pct,diskon_nominal,pajak_pct,subtotal}],subtotal,diskon,pajak,ongkir,biaya_lain,total,confidence}. Jangan mengarang field yang tidak terbaca; gunakan string kosong atau 0.';$model=$this->setting('GEMINI_MODEL')?:'gemini-2.5-flash';$url='https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent?key='.rawurlencode($key);$body=['contents'=>[['parts'=>[['text'=>$prompt],['inline_data'=>['mime_type'=>$mime,'data'=>$base64]]]]],'generationConfig'=>['responseMimeType'=>'application/json','temperature'=>0.1]];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($body),CURLOPT_TIMEOUT=>60]);$resp=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($resp===false||$http>=400)throw new RuntimeException('Gemini OCR gagal: '.($err?:('HTTP '.$http)));$j=json_decode($resp,true);$text=$j['candidates'][0]['content']['parts'][0]['text']??'';$data=json_decode($text,true);if(!is_array($data))throw new RuntimeException('Respons OCR tidak berupa JSON terstruktur.');return ['status'=>'success','data'=>$data,'raw'=>$data,'provider'=>'Gemini','model'=>$model];}
}
